                       c[0,0]*l[1]/(6*l[0]) - c[0,2]/4 - c[0,2]*l[1]*np.tan(g[0])/(6*l[0]) + c[2,0]/4 - c[2,0]*l[1]*np.tan(g[0])/(6*l[0]) - c[2,2]*l[0]/(3*l[1]) + c[2,2]*l[1]*np.tan(g[0])**2/(6*l[0]),
